code2='''from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = [[False] * w for _ in range(h)]
    rects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or seen[r][c]:
                continue
            q = [(r, c)]
            seen[r][c] = True
            comp = []
            while q:
                y, x = q.pop()
                comp.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        if dy == dx == 0:
                            continue
                        ny, nx = y + dy, x + dx
                        if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                            seen[ny][nx] = True
                            q.append((ny, nx))
            r0 = min(y for y, x in comp); r1 = max(y for y, x in comp)
            c0 = min(x for y, x in comp); c1 = max(x for y, x in comp)
            area = (r1-r0+1) * (c1-c0+1)
            # Main shapes are filled rectangles; small components are speckle noise.
            if area >= 4 and r1 > r0 and c1 > c0 and len(comp) / area >= 0.65:
                rects.append((r0, r1, c0, c1, color))
    out = [[bg for _ in range(w)] for _ in range(h)]
    for r0, r1, c0, c1, color in rects:
        for r in range(r0, r1+1):
            for c in range(c0, c1+1):
                out[r][c] = color
    return out
'''
